export const MAKING_BUDGET_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu anggaran",q:"'Anggaran' pribadi adalah...",options:["Rencana tentang bagaimana kamu akan membagi uang yang masuk ke berbagai keperluan","Jumlah uang di dompetmu ditambah uang yang dipinjam dari teman hari ini","Nama sebuah bank tempat orang tua biasa menyimpan uang keluarga besar"],answer:0,explain:"Anggaran memberi tiap rupiah 'tugas': sebagian untuk kebutuhan, sebagian tabungan, sebagian keinginan.",hint:"Rencana untuk memakai uangmu, atau jumlah uang itu sendiri?"},
{n:2,type:"mcq",micro:"Pemasukan",q:"'Pemasukan' adalah...",options:["Barang yang kamu miliki di rumah dan kamar, seperti buku, mainan, pakaian","Uang yang masuk kepadamu (uang saku, hadiah, hasil kerja/jualan)","Uang yang kamu belanjakan untuk jajan, transport, dan keperluan sekolah"],answer:1,explain:"Pemasukan adalah semua uang yang kamu terima dalam suatu periode.",hint:"Uang yang datang, atau uang yang pergi?"},
{n:3,type:"mcq",micro:"Pengeluaran",q:"'Pengeluaran' adalah...",options:["Uang yang kamu terima dari orang tua pada awal minggu sekolah","Tabungan di bank yang belum kamu pakai untuk keperluan apa saja dalam waktu dekat","Uang yang keluar untuk membeli barang/jasa atau membayar kewajiban"],answer:2,explain:"Pengeluaran adalah semua uang yang kamu belanjakan atau bayarkan.",hint:"Uang yang pergi darimu."},
{n:4,type:"mcq",micro:"Rumus dasar anggaran",q:"Hubungan dasar dalam anggaran pribadi:",options:["Pemasukan = Pengeluaran + Tabungan (semua uang masuk dibagi ke pengeluaran & tabungan)","Tabungan = Pemasukan × Pengeluaran (uang masuk dikalikan uang yang sudah dibelanjakan)","Pengeluaran harus lebih besar daripada pemasukan, supaya uang cepat berputar"],answer:0,explain:"Setiap rupiah yang masuk harus 'punya tujuan': sebagian jadi pengeluaran, sebagian jadi tabungan.",hint:"Ke mana perginya semua uang yang masuk?"},
{n:5,type:"mcq",micro:"Surplus & defisit",q:"Bulan ini pemasukan Rina Rp200.000 & pengeluarannya Rp230.000. Ini disebut...",options:["Impas, karena pemasukan sama dengan pengeluaran","Defisit Rp30.000 — pengeluaran melebihi pemasukan","Surplus Rp30.000 — pemasukan melebihi pengeluaran"],answer:1,explain:"Defisit: pengeluaran > pemasukan. Kekurangan Rp30.000 harus ditutup dari tabungan atau utang — tidak bisa terus berlanjut.",hint:"Pengeluaran lebih besar atau lebih kecil dari pemasukan?"},
{n:6,type:"order",micro:"Membuat anggaran sederhana",q:"Urutkan langkah membuat anggaran bulanan sederhana.",items:["Hitung perkiraan total pemasukan bulan ini","Daftar pengeluaran tetap (kebutuhan) & perkiraan biayanya","Tetapkan jumlah tabungan yang disisihkan","Alokasikan sisa untuk keinginan & berbagi, lalu pastikan totalnya tidak melebihi pemasukan"],answer:[0,1,2,3],explain:"Pemasukan → kebutuhan → tabungan → sisa untuk keinginan; cek total ≤ pemasukan.",hint:"Kamu perlu tahu berapa yang masuk sebelum bisa membaginya."},
{n:7,type:"mcq",micro:"Anggaran = uang punya tujuan",q:"Prinsip 'setiap rupiah punya tujuan' berarti...",options:["Kamu harus menghabiskan semua uang sampai tak ada sisa pada hari yang sama saat menerimanya dari orang tua","Uang tidak perlu direncanakan sebelumnya, karena yang penting dicatat hanya pada akhir bulan nanti","Kamu memutuskan di depan ke mana semua uangmu akan pergi, sehingga tidak ada yang 'menghilang tanpa jejak'"],answer:2,explain:"Kalau semua uang punya alokasi (termasuk 'hiburan' & 'cadangan'), lebih sedikit yang terbuang tanpa disadari.",hint:"Apa yang terjadi pada uang yang tidak dialokasikan ke mana pun?"},
{n:8,type:"mcq",micro:"Anggaran mingguan vs bulanan",q:"Untuk uang saku yang diterima mingguan, anggaran...",options:["Bisa disusun per minggu, atau dikumpulkan & direncanakan per bulan — pilih yang paling mudah kamu ikuti","Harus bulanan, sehingga uang saku mingguan wajib ditahan dulu sampai akhir bulan baru dicatat olehmu dan orang tuamu","Tidak bisa dibuat untuk uang saku, sebab anggaran hanya cocok untuk gaji orang dewasa yang bekerja"],answer:0,explain:"Periode anggaran sebaiknya cocok dengan ritme pemasukanmu & seberapa mudah kamu memantaunya.",hint:"Kamu menerima uang tiap berapa lama?"},
{n:9,type:"mcq",micro:"Contoh pembagian",q:"Uang saku Rp50.000/minggu. Contoh pembagian yang masuk akal:",options:["Semua Rp50.000 untuk keinginan minggu itu, karena kebutuhan transport dan makan bisa dimintakan lagi","Kebutuhan (transport+makan) Rp28.000; tabungan Rp10.000; keinginan Rp8.000; cadangan Rp4.000","Keinginan Rp45.000; sisanya Rp5.000 dibagi untuk transport, makan, dan tabungan seminggu penuh"],answer:1,explain:"Angka pastinya bergantung keadaan, tapi polanya: kebutuhan & tabungan diamankan dulu.",hint:"Bagian mana yang ditetapkan lebih dulu?"},
{n:10,type:"mcq",micro:"Menabung sebagai pos anggaran",q:"Dalam anggaran, tabungan sebaiknya...",options:["Hanya diisi kalau ada uang lebih di akhir bulan, sehingga bila tak ada sisa tidak menabung.","Tidak dimasukkan ke anggaran, karena menabung urusan yang terpisah dari rencana keuangan","Menjadi pos tersendiri yang disisihkan di awal, bukan 'sisa yang kalau ada'"],answer:2,explain:"Menempatkan tabungan sebagai pos yang dibayar lebih dulu ('bayar diri sendiri dulu') membuatnya lebih pasti.",hint:"Kapan lebih mungkin ada uang untuk ditabung?"},
{n:11,type:"tf",micro:"Anggaran bukan hukuman",q:"Benar atau Salah: Anggaran pada dasarnya adalah daftar larangan yang membuat hidup terasa berat, bukan alat untuk mencapai tujuan & memakai uang dengan tenang.",answer:false,explain:"Anggaran sebaiknya dilihat sebagai 'rencanaku untuk uangku' — alat untuk mencapai tujuan & tenang, bukan hukuman. Yang dilihat begitu lebih mungkin dijalankan.",hint:"'Kamu tidak boleh' atau 'inilah rencanamu'?"},
{n:12,type:"mcq",micro:"Melacak pengeluaran",q:"Mencatat setiap pengeluaran selama seminggu berguna karena...",options:["Menunjukkan ke mana uang benar-benar pergi (sering mengejutkan) & menemukan tempat untuk berhemat","Membuat catatan terlihat rapi saja supaya guru atau orang tua menilai kita teliti sekali","Tidak ada gunanya karena pengeluaran sudah diketahui tanpa perlu dicatat setiap hari"],answer:0,explain:"Banyak orang kaget melihat total pengeluaran kecil (jajan harian) ternyata besar bila dijumlahkan.",hint:"Bagaimana kamu tahu ke mana uangmu pergi kalau tidak dicatat?"},
{n:13,type:"mcq",micro:"Pengeluaran kecil menumpuk",q:"Jajan Rp3.000 setiap hari sekolah (5 hari) selama 4 minggu berjumlah...",options:["Rp15.000","Rp60.000","Rp12.000"],answer:1,explain:"Rp3.000 × 5 × 4 = Rp60.000. Pengeluaran kecil yang rutin menjadi besar; anggaran membuatnya terlihat.",hint:"Hitung per minggu, lalu kalikan 4."},
{n:14,type:"mcq",micro:"Anggaran & kejutan",q:"Menyisihkan pos 'cadangan/tak terduga' dalam anggaran berguna untuk...",options:["Membeli keinginan yang sedang populer tanpa perlu mengubah pos lain di anggaran","Tidak ada gunanya karena pengeluaran kecil tak perlu dianggarkan dan bisa dikerjakan belakangan","Menutup pengeluaran mendadak kecil (fotokopi tambahan, iuran dadakan) tanpa merusak pos lain"],answer:2,explain:"Pos cadangan kecil menyerap kejutan sehari-hari sehingga anggaran tidak langsung 'jebol'.",hint:"Apa yang terjadi kalau ada pengeluaran mendadak & semua pos sudah ketat?"},
{n:15,type:"tf",micro:"Anggaran menyertakan keinginan",q:"Benar atau Salah: Anggaran yang baik biasanya menyisakan porsi khusus untuk keinginan/kesenangan, bukan hanya kebutuhan & tabungan.",answer:true,explain:"Anggaran tanpa ruang untuk kesenangan sulit dijalani lama. Porsi keinginan yang direncanakan membuat pengeluaran itu disengaja.",hint:"Bisakah kamu menaati anggaran yang tidak pernah membolehkan hal menyenangkan?"},
{n:16,type:"mcq",micro:"Menghitung sisa",q:"Uang saku mingguan Rp50.000. Kamu ingin: jajan Rp20.000, tabung Rp20.000, berbagi Rp5.000. Berapa sisa yang belum dialokasikan?",options:["Rp5.000","Rp10.000","Rp0"],answer:0,explain:"Rp20.000 + Rp20.000 + Rp5.000 = Rp45.000. Sisa Rp50.000 − Rp45.000 = Rp5.000 (bisa jadi cadangan).",hint:"Jumlahkan semua rencana, lalu kurangkan dari total."},
{n:17,type:"mcq",micro:"Anggaran & kebutuhan yang tidak pasti",q:"Untuk pengeluaran yang jumlahnya berubah-ubah tiap minggu (makan, transport saat ada kegiatan tambahan), cara menganggarkannya:",options:["Tidak perlu dianggarkan karena pemasukan yang tidak tetap tak bisa diperkirakan, jadi lihat saja nanti","Perkirakan rata-rata dari beberapa minggu terakhir & tambahkan sedikit penyangga","Anggap nol karena pemasukan tak tentu tak boleh dimasukkan ke rencana keuangan"],answer:1,explain:"Pengeluaran yang bervariasi dianggarkan dengan perkiraan rata-rata plus buffer, lalu disesuaikan seiring waktu.",hint:"Bagaimana menganggarkan sesuatu yang tidak sama tiap minggu?"},
{n:18,type:"mcq",micro:"Anggaran keluarga vs pribadi",q:"Anggaran keluarga (listrik, sewa, makan pokok) & anggaran uang sakumu...",options:["Sepenuhnya tidak berhubungan karena anggaran keluarga memakai prinsip yang berbeda total","Persis sama sehingga angka dan pos anggaran pelajar bisa disalin utuh untuk keluarga","Punya prinsip yang sama (pemasukan dibagi ke pos-pos, kebutuhan dulu) tapi skala & item berbeda"],answer:2,explain:"Prinsip menganggarkan berlaku di semua skala; yang berbeda hanya besaran & jenis pengeluarannya.",hint:"Apakah membagi uang ke pos-pos berlaku untuk keluarga & untuk uang saku?"},
{n:19,type:"mcq",micro:"Anggaran sederhana lebih baik dari tidak ada",q:"Anggaran yang sangat sederhana (kebutuhan / tabungan / keinginan, tiga angka) tetap berguna karena...",options:["Memberi arah & batas; anggaran sempurna yang tidak pernah dibuat kalah dari anggaran sederhana yang dijalankan","Anggaran sederhana tidak berguna, karena tiga angka saja terlalu sedikit untuk mengatur uang dengan baik bagi pelajar seusiamu","Hanya anggaran yang sangat rinci sampai ke recehan yang membantu, jadi yang sederhana tak perlu dibuat"],answer:0,explain:"Kesederhanaan meningkatkan kemungkinan kamu benar-benar memakainya. Mulai sederhana, perbaiki seiring waktu.",hint:"Mana yang lebih baik: rencana 3 pos yang dijalankan, atau rencana 20 pos yang diabaikan?"},
{n:20,type:"open",micro:"Menyusun anggaran mingguan pertamamu",q:"Uang sakumu Rp60.000/minggu. Susun anggaran yang mencakup: kebutuhan (transport, makan/jajan sehat), tabungan, keinginan, & cadangan. Tuliskan jumlah tiap pos & pastikan totalnya tidak melebihi Rp60.000.",explain:"Anggaran baik: total ≤ pemasukan, ada pos tabungan yang disisihkan lebih dulu, pemisahan jelas kebutuhan/keinginan, & pos cadangan kecil untuk kejutan.",hint:"Jumlahkan semua pos & periksa tidak lebih dari Rp60.000; taruh tabungan sebagai prioritas.",sample:"Contoh: transport Rp15.000; makan/jajan sehat Rp18.000; tabungan Rp15.000; keinginan (jajan tambahan/hiburan) Rp8.000; cadangan tak terduga Rp4.000. Total = Rp60.000. Tabungan disisihkan di awal minggu, bukan menunggu sisa. Kalau seminggu ada kegiatan tambahan yang butuh transport lebih, ambil dari pos cadangan atau kurangi keinginan minggu itu."},
{n:21,type:"mcq",micro:"Aturan 50/30/20",q:"Panduan '50/30/20' membagi pemasukan: 50% kebutuhan, 30% keinginan, 20% tabungan. Dari Rp100.000, berapa untuk tabungan?",options:["Rp30.000","Rp20.000","Rp50.000"],answer:1,explain:"20% dari Rp100.000 = Rp20.000. Panduan ini bisa disesuaikan dengan keadaan masing-masing.",hint:"Hitung 20% dari 100.000."},
{n:22,type:"mcq",micro:"Menyesuaikan aturan panduan",q:"Aturan seperti 50/30/20 sebaiknya diperlakukan sebagai...",options:["Aturan mutlak yang tidak boleh diubah sedikit pun, bagaimanapun keadaan dan kebutuhan keuanganmu berbeda dari orang lain setiap saat","Tidak berguna karena angka persentase tak mungkin cocok untuk orang mana pun dalam keadaan apa saja, sehingga lebih baik dihitung ulang tiap hari","Titik awal yang disesuaikan dengan keadaanmu (mis. lebih banyak untuk kebutuhan bila transport mahal, atau lebih banyak tabungan untuk tujuan mendesak)"],answer:2,explain:"Panduan memberi kerangka; proporsi pastinya bergantung penghasilan, biaya hidup, & tujuanmu.",hint:"Apakah semua orang punya biaya transport & tujuan yang sama?"},
{n:23,type:"classify",micro:"Mengelompokkan pengeluaran",q:"Kelompokkan tiap pengeluaran ke 'Kebutuhan', 'Keinginan', atau 'Tabungan/Cadangan'.",items:["Ongkos angkot ke sekolah","Menyisihkan Rp15.000/minggu untuk sepeda","Minuman kekinian setiap hari","Buku tulis yang habis"],groups:["Kebutuhan","Keinginan","Tabungan/Cadangan"],answer:{"Kebutuhan":["Ongkos angkot ke sekolah","Buku tulis yang habis"],"Keinginan":["Minuman kekinian setiap hari"],"Tabungan/Cadangan":["Menyisihkan Rp15.000/minggu untuk sepeda"]},explain:"Mengelompokkan pengeluaran membantu melihat apakah proporsi antar kelompok sehat.",hint:"Apakah ini menjaga hidup berjalan, menambah kesenangan, atau untuk nanti?"},
{n:24,type:"mcq",micro:"Metode amplop",q:"'Metode amplop' berarti...",options:["Memisahkan uang untuk tiap pos ke amplop terpisah; saat amplop kosong, pos itu habis untuk periode ini","Menyimpan seluruh uang di dalam satu amplop besar saja, lalu mengambilnya sedikit demi sedikit tanpa pembagian pos","Mengirim uang lewat kantor pos kepada saudara atau teman supaya uangnya aman dari godaan jajan sehari-hari"],answer:0,explain:"Metode amplop membuat batas tiap pos terlihat & terasa nyata — kamu tahu persis berapa yang tersisa.",hint:"Apa yang terjadi saat amplop 'jajan' sudah kosong di hari Kamis?"},
{n:25,type:"mcq",micro:"Anggaran nol (zero-based)",q:"'Anggaran berbasis nol' berarti...",options:["Kamu tidak boleh menabung sepeser pun, karena semua pemasukan harus habis dibelanjakan menjadi nol di akhir bulan","Kamu mengalokasikan setiap rupiah pemasukan ke suatu pos (termasuk tabungan & cadangan) sampai sisa alokasi = nol","Kamu menganggarkan Rp0 untuk setiap pos, sehingga seluruh pengeluaran dibiarkan terjadi tanpa rencana, dan itu dianggap normal"],answer:1,explain:"Setiap rupiah diberi tugas. 'Nol' berarti tidak ada uang yang tidak dialokasikan, bukan tidak ada uang.",hint:"Kalau semua uang sudah punya tugas, berapa yang tersisa 'tanpa rencana'?"},
{n:26,type:"mcq",micro:"Anggaran & pengeluaran tak terduga besar",q:"Anggaran bulanan biasa tidak cukup untuk pengeluaran besar yang jarang (seragam baru tiap tahun, alat mahal). Cara menanganinya:",options:["Berutang kepada orang lain pada saat pengeluaran besar itu datang, lalu dicicil dari uang saku bulan-bulan berikutnya","Abaikan saja sampai kejadian itu benar-benar terjadi, lalu pikirkan solusinya ketika tagihannya sudah datang","Sisihkan sedikit tiap bulan ke 'dana tujuan' khusus, sehingga saat pengeluaran besar itu tiba, uangnya sudah siap"],answer:2,explain:"Pengeluaran besar berkala 'dicicil ke depan' lewat tabungan tujuan, bukan dihadapi sebagai kejutan.",hint:"Kalau kamu tahu seragam baru dibutuhkan tiap tahun, kapan sebaiknya mulai menyiapkan uangnya?"},
{n:27,type:"tf",micro:"Anggaran perlu ditinjau",q:"Benar atau Salah: Sekali sebuah anggaran dibuat, ia tidak perlu ditinjau atau dibandingkan dengan pengeluaran nyata — cukup dijalankan apa adanya selamanya.",answer:false,explain:"Anggaran adalah alat yang diperbaiki terus. Meninjaunya di akhir tiap periode (rencana vs kenyataan) & menyesuaikannya untuk periode berikutnya adalah cara membuatnya makin akurat.",hint:"Bagaimana anggaran bulan depan bisa lebih akurat?"},
{n:28,type:"mcq",micro:"Rencana vs kenyataan",q:"Kamu menganggarkan Rp15.000/minggu untuk jajan tapi selalu habis Rp25.000. Respons yang tepat:",options:["Cari tahu sebabnya; sesuaikan anggaran (jadi Rp20.000 dengan memangkas pos lain) ATAU cari cara menekan jajan nyata ke Rp15.000 — jangan cuma mengabaikan","Abaikan saja, karena angka anggaran tak penting dan yang terpenting uangnya dipakai sesuai keinginan, sebagaimana biasanya, asal tak berutang","Berhenti membuat anggaran, sebab anggaran gagal bila pengeluaran melampaui angka rencana, lalu pakai uang sesuka hati tiap hari"],answer:0,explain:"Selisih besar berulang antara rencana & kenyataan adalah sinyal: perkiraanmu salah, atau kebiasaanmu perlu berubah.",hint:"Apa dua cara mendamaikan 'anggaran Rp15.000' & 'pengeluaran nyata Rp25.000'?"},
{n:29,type:"mcq",micro:"Anggaran & pemasukan tidak tetap",q:"Kalau pemasukanmu berubah-ubah, cara membuat anggaran yang cocok:",options:["Tidak bisa membuat anggaran, karena anggaran hanya bisa dibuat bila pemasukan tetap sama tiap bulan, jadi cukup dicatat saja setelah uangnya habis","Anggarkan berdasarkan pemasukan terendah yang biasa kamu terima; kalau lebih, alokasikan kelebihannya (mis. ke tabungan/tujuan)","Anggarkan berdasarkan pemasukan tertinggi yang pernah kamu terima, supaya semua kebutuhan dan keinginan tercakup sepenuhnya"],answer:1,explain:"Menganggarkan konservatif (dari pemasukan terendah) mencegah defisit di bulan yang 'kurang'; kelebihan di bulan 'lebih' jadi bonus untuk tabungan.",hint:"Mana yang lebih aman: merencanakan dari angka rendah atau angka tinggi?"},
{n:30,type:"order",micro:"Meninjau & menyesuaikan anggaran",q:"Urutkan langkah meninjau anggaran di akhir bulan.",items:["Kumpulkan catatan pengeluaran nyata bulan ini per pos","Bandingkan dengan angka yang dianggarkan; tandai pos yang meleset jauh","Cari sebab tiap selisih besar (perkiraan salah? kejutan? kebiasaan?)","Sesuaikan angka pos untuk bulan depan berdasarkan temuan"],answer:[0,1,2,3],explain:"Kumpulkan data nyata → bandingkan → cari sebab → sesuaikan.",hint:"Kamu perlu angka nyata untuk membandingkannya dengan rencana."},
{n:31,type:"mcq",micro:"Anggaran terlalu ketat",q:"Anggaran yang menyisihkan porsi sangat besar & tidak menyisakan ruang untuk kesenangan sama sekali...",options:["Strategi terbaik, karena semakin ketat anggarannya semakin cepat kamu mencapai semua tujuanmu nanti dengan lebih mudah","Menjamin tujuan tercapai, sebab orang yang menahan diri sepenuhnya tak merasa lelah atau menyerah","Sering tidak bertahan — orang menyerah karena terasa menyiksa; anggaran seimbang lebih berkelanjutan"],answer:2,explain:"Seperti diet yang terlalu ketat, anggaran yang ekstrem sering berujung 'menyerah total'. Sedikit ruang untuk menikmati membuatnya bertahan.",hint:"Apa yang terjadi pada rencana yang melarang semua hal menyenangkan?"},
{n:32,type:"mcq",micro:"Kategori yang cukup, tidak berlebihan",q:"Untuk anggaran uang saku pelajar, jumlah kategori yang wajar:",options:["Sekitar 4–6 (mis. transport, makan, tabungan, keinginan, cadangan) — cukup untuk berguna, tidak sampai membebani","20+ kategori sangat rinci supaya setiap pengeluaran kecil terlacak sampai ke recehan setiap harinya","Tepat 1 kategori saja supaya anggaran terlihat sederhana dan tak membingungkan anggota keluarga lain"],answer:0,explain:"Terlalu banyak kategori membuat pelacakan melelahkan; terlalu sedikit tidak memberi wawasan. Sekitar 4–6 sering pas.",hint:"Berapa kategori yang bisa kamu lacak tanpa merasa terbebani?"},
{n:33,type:"tf",micro:"Anggaran membantu mencapai tujuan",q:"Benar atau Salah: Menaruh tujuan tabungan sebagai pos anggaran tetap tidak lebih efektif daripada sekadar berharap 'menabung dari sisa' di akhir periode.",answer:false,explain:"Tujuan yang punya pos anggaran tetap 'dibayar' setiap periode, bukan tergantung apakah ada sisa — jadi jauh lebih mungkin tercapai.",hint:"Mana yang lebih pasti: pos tetap, atau harapan ada sisa?"},
{n:34,type:"mcq",micro:"Anggaran & utang",q:"Kalau anggaranmu terus defisit (pengeluaran > pemasukan) & kamu menutupnya dengan pinjam...",options:["Berarti anggaran tak perlu dibuat lagi, karena kekurangannya bisa ditutup dengan pinjaman baru setiap saat, asal bunganya kecil","Ini tidak berkelanjutan; kamu harus menaikkan pemasukan, memangkas pengeluaran, atau keduanya — utang yang menumpuk memperburuk keadaan","Bisa berlanjut tanpa masalah, sebab utang kecil yang terus ditambah tak akan menumpuk, asalkan dicicil pelan-pelan oleh semua anggota keluarga"],answer:1,explain:"Defisit yang ditutup utang secara terus-menerus adalah lubang yang makin dalam. Anggaran harus menyeimbangkan pemasukan & pengeluaran.",hint:"Apa yang terjadi kalau setiap bulan kamu berutang untuk menutup kekurangan?"},
{n:35,type:"mcq",micro:"Menyesuaikan saat keadaan berubah",q:"Semester baru: transportmu jadi lebih jauh & mahal. Terhadap anggaran:",options:["Biarkan anggaran lama dan berharap cukup, sebab biaya transport kadang turun sendiri bulan depan","Batalkan anggaran karena perubahan transport membuat seluruh rencana tak berlaku lagi bagi keluarga","Naikkan pos transport & imbangi dengan memangkas pos lain (atau menambah pemasukan) agar total tetap seimbang"],answer:2,explain:"Perubahan biaya nyata menuntut penyesuaian anggaran, bukan mengabaikannya.",hint:"Kalau satu pos harus naik, dari mana penyesuaiannya?"},
{n:36,type:"mcq",micro:"Anggaran & keputusan pembelian",q:"Anggaran membantu keputusan pembelian sehari-hari dengan...",options:["Memberi jawaban cepat: 'apakah pos keinginan minggu ini masih ada?' — kalau habis, tunda","Membuat setiap pembelian butuh perhitungan panjang dan rumit sehingga kamu enggan membeli","Melarang semua pembelian kecil yang tak tercatat di anggaran, walau nilainya hanya beberapa ribu"],answer:0,explain:"Anggaran yang sudah disusun mengubah banyak keputusan jadi cek cepat, bukan pergulatan tiap kali.",hint:"Apa pertanyaan singkat yang anggaran bantu jawab di toko?"},
{n:37,type:"tf",micro:"Anggaran pertama jarang sempurna",q:"Benar atau Salah: Wajar jika anggaran pertamamu perlu diperbaiki setelah kamu melihat pengeluaran nyata — perkiraan awal sering meleset.",answer:true,explain:"Anggaran adalah dugaan terbaik di awal. Setelah 1–2 periode data nyata, kamu bisa membuatnya jauh lebih akurat.",hint:"Apakah tebakan pertama tentang pengeluaranmu pasti tepat?"},
{n:38,type:"mcq",micro:"Anggaran & tujuan bersama keluarga",q:"Kalau kamu ikut menyusun anggaran belanja keluarga, prinsip yang berlaku:",options:["Habiskan seluruh uang belanja tanpa rencana sampai ke akhir bulan, lalu lihat berapa yang tersisa untuk kebutuhan","Amankan pokok (beras, lauk, kebersihan, tagihan) dulu, tetapkan tabungan/darurat, lalu barang tambahan dari sisa","Beli barang tambahan yang menyenangkan lebih dulu, baru sisanya dipakai untuk kebutuhan pokok dan tagihan"],answer:1,explain:"Urutan prioritas (kebutuhan → tabungan → keinginan) sama di tingkat keluarga.",hint:"Apa yang harus ada di keranjang lebih dulu?"},
{n:39,type:"mcq",micro:"Alat untuk menganggarkan",q:"Kamu bisa membuat & melacak anggaran dengan...",options:["Hanya dengan aplikasi berbayar yang mahal, karena catatan di buku atau ponsel biasa tak bisa diandalkan, dan harus dipakai ahli keuangan yang berpengalaman","Tak ada alat yang bisa dipakai pelajar, karena anggaran hanya bisa dibuat orang dewasa yang punya penghasilan sendiri dan tetap","Buku catatan, aplikasi catatan di ponsel, spreadsheet sederhana, atau aplikasi anggaran — pilih yang paling konsisten kamu pakai"],answer:2,explain:"Alat terbaik adalah yang benar-benar kamu gunakan. Mulai dengan yang paling mudah bagimu.",hint:"Alat mana yang akan kamu buka setiap hari tanpa merasa repot?"},
{n:40,type:"open",micro:"Membandingkan rencana vs kenyataan",q:"Kamu menganggarkan: transport Rp15.000, makan Rp18.000, tabungan Rp15.000, keinginan Rp8.000, cadangan Rp4.000 (total Rp60.000). Kenyataan seminggu: transport Rp15.000, makan Rp22.000, tabungan Rp15.000, keinginan Rp14.000, cadangan Rp0 (total Rp66.000 — kamu pinjam Rp6.000). Analisis: (1) pos mana yang meleset & seberapa, (2) kemungkinan sebabnya, (3) penyesuaian untuk minggu depan.",explain:"Jawaban baik mengidentifikasi pos yang meleset dengan angka, menebak sebab yang masuk akal, & menyesuaikan anggaran (menaikkan yang terlalu rendah, menurunkan yang lain) + aturan perilaku, sambil menjaga total ≤ pemasukan & merencanakan pengembalian pinjaman.",hint:"Damaikan anggaran dengan kenyataan: naikkan yang salah perkiraan, & tekan yang membengkak karena kebiasaan.",sample:"(1) Meleset: makan +Rp4.000 (dari Rp18.000 jadi Rp22.000); keinginan +Rp6.000 (dari Rp8.000 jadi Rp14.000); total defisit Rp6.000 (harus pinjam). Transport & tabungan sesuai. (2) Sebab: makan mungkin karena beli lauk yang lebih mahal atau ada hari lapar ekstra; keinginan membengkak karena beli minuman kekinian 2x lebih sering dari rencana / ada ajakan jajan bareng teman. (3) Penyesuaian minggu depan: naikkan pos makan jadi Rp20.000 (realistis) & imbangi dengan menurunkan keinginan jadi Rp6.000; tetapkan aturan 'jajan minuman maksimal 2x/minggu'; bawa bekal 1–2 hari untuk menekan makan; kembalikan pinjaman Rp6.000 dari cadangan minggu depan atau dari uang tak terduga. Total tetap Rp60.000."},
{n:41,type:"mcq",micro:"Anggaran & prioritas saat sempit",q:"Bulan ini pemasukan turun & anggaran tidak muat. Urutan memangkas:",options:["Pangkas keinginan & 'nilai tambah' dulu; lindungi kebutuhan pokok & (bila mungkin) tabungan/darurat","Pangkas kebutuhan pokok seperti makan dan transport sekolah dulu, sebab keinginan sudah terlanjur direncanakan","Pangkas semua pos rata dengan persentase sama, tanpa membedakan mana yang penting dan tidak bagi keluarga"],answer:0,explain:"Saat harus memotong, lindungi yang menjaga hidup berjalan & keamananmu; korbankan yang bisa ditunda.",hint:"Bagian mana yang tanpa itu ada masalah serius?"},
{n:42,type:"mcq",micro:"Anggaran & pemasukan bertambah",q:"Uang sakumu naik dari Rp60.000 ke Rp80.000/minggu. Kebiasaan sehat:",options:["Habiskan seluruh kenaikan untuk keinginan baru, karena kenaikan uang saku memang pantas dinikmati sepenuhnya dan segera","Alokasikan sebagian besar kenaikan (mis. Rp15.000) ke tabungan/tujuan, & sebagian kecil untuk menaikkan kualitas hidup — bukan menaikkan semua pengeluaran","Naikkan semua pos pengeluaran secara proporsional, sehingga porsi tabunganmu tidak bertambah sedikit pun dari sebelumnya setiap saat"],answer:1,explain:"Membiarkan tabungan tumbuh saat pemasukan naik ('menghindari inflasi gaya hidup') membangun keamanan lebih cepat.",hint:"Ke mana sebaiknya sebagian besar 'uang tambahan' pergi?"},
{n:43,type:"mcq",micro:"Anggaran & tujuan besar",q:"Kamu ingin laptop Rp2.400.000 dalam setahun. Cara memasukkannya ke anggaran:",options:["Berutang Rp2.400.000 sekarang agar laptop bisa dibeli segera, lalu bayar dengan uang saku di bulan-bulan mendatang","Berharap ada rezeki besar mendadak sebelum setahun berlalu, sehingga tidak perlu menyisihkan uang tiap bulan","Rp2.400.000 ÷ 12 = Rp200.000/bulan sebagai pos 'dana laptop' — kalau tidak muat, sesuaikan tenggat atau target"],answer:2,explain:"Tujuan besar dipecah menjadi pos anggaran bulanan. Kalau pos itu tidak muat, ubah tenggat/target — jangan paksakan lewat utang.",hint:"Bagi harga dengan jumlah bulan untuk mendapat pos bulanannya."},
{n:44,type:"mcq",micro:"Anggaran & langganan",q:"Layanan berlangganan (musik, gim) dalam anggaran perlu diperhatikan karena...",options:["Biaya kecil bulanan mudah terlupa & menumpuk; masukkan sebagai pos & tinjau berkala mana yang benar-benar dipakai","Gratis karena layanan langganan baru menarik biaya setelah dipakai sebulan penuh di aplikasi ponsel","Tidak membebani anggaran karena nilainya kecil dibanding uang saku bulanan keluarga yang diterima"],answer:0,explain:"Langganan yang tidak dipakai adalah 'kebocoran' tersembunyi. Menganggarkannya secara eksplisit membuatnya terlihat & bisa dievaluasi.",hint:"Berapa layanan yang kamu bayar tapi jarang pakai?"},
{n:45,type:"order",micro:"Menyusun anggaran bulanan lengkap",q:"Urutkan langkah menyusun anggaran bulanan yang lengkap.",items:["Hitung total pemasukan bulan ini (pakai perkiraan konservatif bila tidak tetap)","Daftar & perkirakan kebutuhan tetap + pos tabungan/darurat","Alokasikan sisa ke keinginan, berbagi, & dana tujuan; pastikan total = pemasukan","Sepanjang bulan: catat pengeluaran; akhir bulan: bandingkan & sesuaikan"],answer:[0,1,2,3],explain:"Pemasukan → kebutuhan & tabungan → alokasi sisa (total = pemasukan) → lacak & tinjau.",hint:"Pemasukan dulu, lalu bagi ke pos-pos sampai habis (termasuk tabungan)."},
{n:46,type:"mcq",micro:"Anggaran & keputusan besar",q:"Sebelum membeli sesuatu yang besar (di luar pos rutin), anggaran membantu dengan...",options:["Membuat pembelian besar mustahil dilakukan, karena anggaran biasanya terlalu kecil untuk barang mahal, sehingga lebih baik ditunda terus","Menunjukkan apakah ada dana tujuan untuk itu, atau berapa lama kamu perlu menabung — sehingga keputusan berbasis fakta, bukan dorongan","Melarang semua pembelian besar, sehingga kamu tak boleh membeli barang yang harganya mahal, tanpa menimbang kebutuhan atau tujuan menabung"],answer:1,explain:"Anggaran mengubah 'aku ingin ini' menjadi 'ini butuh X minggu menabung, & biaya peluangnya Y' — keputusan yang lebih jernih.",hint:"Apa yang anggaran tunjukkan tentang 'seberapa terjangkau' pembelian besar?"},
{n:47,type:"mcq",micro:"Anggaran 'lentur' untuk hal yang tak terduga",q:"Beberapa orang menambahkan pos 'lentur/kesenangan spontan' kecil dalam anggaran. Gunanya:",options:["Untuk pengeluaran besar yang sudah direncanakan jauh hari oleh seluruh anggota keluarga dan dicatat lengkap di buku kas","Tidak ada gunanya karena pengeluaran spontan sebaiknya dilarang agar anggaran tetap rapi dan disiplin sepanjang bulan penuh bagi pelajar","Memberi izin untuk pengeluaran spontan kecil tanpa merasa melanggar anggaran — membuat anggaran terasa manusiawi & lebih mungkin ditaati"],answer:2,explain:"Pos 'lentur' mengakui bahwa hidup punya kejutan menyenangkan. Merencanakannya lebih baik daripada berpura-pura tidak akan terjadi.",hint:"Apa yang lebih realistis: anggaran yang tidak pernah mengizinkan hal spontan, atau yang punya sedikit ruang untuknya?"},
{n:48,type:"mcq",micro:"Anggaran & kejujuran pada diri",q:"Anggaran hanya berguna kalau...",options:["Angkanya jujur mencerminkan pemasukan & pengeluaran nyatamu, & kamu benar-benar melacaknya — bukan angka 'ideal' yang tidak kamu ikuti","Terlihat rapi karena angkanya bulat dan seimbang sehingga mudah diingat oleh pembuat anggaran dan orang yang melihatnya","Dibuat sekali lalu dilupakan karena anggaran yang bagus tak perlu dilihat lagi sesudahnya, cukup disimpan di laci kamar"],answer:0,explain:"Anggaran 'khayalan' (angka yang kamu harap, bukan yang nyata) tidak membantu. Kejujuran & pelacakan membuatnya bekerja.",hint:"Apa gunanya anggaran yang tidak mencerminkan kenyataan & tidak diikuti?"},
{n:49,type:"mcq",micro:"Anggaran untuk beberapa tujuan",q:"Kamu punya 3 dana tujuan (darurat, sepeda, kado). Cara memasukkannya ke anggaran:",options:["Hanya menabung untuk tujuan yang paling kamu inginkan saja, sedangkan dana darurat dan kado ditabung kalau ingat","Masing-masing pos tersendiri dengan jumlah berkala; prioritaskan yang mendesak/penting bila total tidak muat","Satu pos 'tabungan' campuran saja, lalu dibagi-bagi belakangan sesuai kebutuhan yang kebetulan muncul nanti"],answer:1,explain:"Memisahkan tiap tujuan sebagai pos memungkinkan memantau kemajuan masing-masing & memprioritaskan saat dana terbatas.",hint:"Bagaimana kamu tahu kemajuan tiap tujuan kalau semuanya dicampur?"},
{n:50,type:"mcq",micro:"Anggaran & tekanan sosial",q:"Teman mengajak kegiatan berbayar yang tidak ada dalam anggaranmu minggu ini. Respons berbasis anggaran:",options:["Ikut saja tanpa menghiraukan anggaran, karena kesempatan bersenang-senang bersama teman tidak datang dua kali, sebagaimana biasanya","Pinjam uang kepada teman atau kakak untuk ikut, lalu kembalikan setelah menerima uang saku berikutnya","Cek pos keinginan/lentur; kalau tidak cukup, tawarkan alternatif gratis atau ikut lain kali saat sudah dianggarkan — bukan berutang atau merusak pos lain"],answer:2,explain:"Anggaran memberi dasar yang jelas untuk mengatakan 'belum bisa minggu ini' tanpa merasa bersalah.",hint:"Apa yang anggaran bantu kamu putuskan tanpa merasa pelit atau tertekan?"},
{n:51,type:"open",micro:"Menyusun anggaran bulanan pribadi",q:"Susun anggaran bulanan pribadi. Sertakan: (1) total pemasukan (uang saku + lainnya), (2) pos kebutuhan tetap + biayanya, (3) pos tabungan/darurat, (4) 1–2 dana tujuan + jumlah berkala, (5) pos keinginan & pos cadangan/lentur, (6) total (harus = pemasukan), (7) cara kamu melacak & kapan meninjau.",explain:"Anggaran baik: total = pemasukan (berbasis nol), kebutuhan & tabungan/darurat sebagai prioritas, dana tujuan sebagai pos, ruang untuk keinginan & lentur, & rencana pelacakan + tinjauan.",hint:"Bagi pemasukan ke pos-pos sampai sisa alokasi nol; tabungan & darurat masuk sebelum keinginan.",sample:"Contoh: (1) Pemasukan: uang saku Rp60.000/minggu ≈ Rp240.000/bulan + bantu paman Rp80.000/bulan = Rp320.000. (2) Kebutuhan: transport Rp90.000, makan Rp90.000, keperluan sekolah Rp25.000 = Rp205.000. (3) Dana darurat: Rp30.000/bulan (sampai target Rp180.000). (4) Dana tujuan: sepatu lari Rp30.000/bulan; kado ibu Rp25.000/bulan (3 bulan). (5) Keinginan Rp15.000/bulan; cadangan/lentur Rp15.000/bulan. (6) Total: 205 + 30 + 30 + 25 + 15 + 15 = Rp320.000 = pemasukan ✓. (7) Lacak: catat tiap pengeluaran di aplikasi catatan ponsel per pos, setiap hari. Tinjau tiap akhir bulan: bandingkan pos nyata vs rencana, cari sebab selisih, sesuaikan bulan depan."},
{n:52,type:"mcq",micro:"Anggaran & pemasukan musiman",q:"Kalau kamu dapat pemasukan besar sesekali (uang lebaran, hadiah, hasil jualan bazar), cara menganggarkannya:",options:["Jangan langsung habiskan; alokasikan ke pos — sebagian ke tabungan/tujuan, sebagian untuk kebutuhan bulan-bulan sepi, sebagian boleh dinikmati","Habiskan semuanya saat itu juga karena 'rezeki' memang harus dinikmati, dan anggaran hanya berlaku untuk uang rutin setiap saat","Simpan saja di dompet begitu saja dan lupakan, lalu pakai sedikit-sedikit tanpa mencatat ke pos mana pun"],answer:0,explain:"Pemasukan besar sesekali paling berharga bila 'disebar' ke tujuan & bulan-bulan kurus, bukan habis dalam sekejap.",hint:"Apa yang biasanya terjadi pada 'uang besar mendadak' yang tidak dialokasikan?"},
{n:53,type:"tf",micro:"Anggaran mengurangi stres keuangan",q:"Benar atau Salah: Memiliki anggaran yang jelas & diikuti justru menambah kecemasan tentang uang dibanding tidak punya rencana sama sekali.",answer:false,explain:"Sebaliknya. Ketidakpastian ('cukup nggak ya?') adalah sumber stres; anggaran menggantinya dengan rencana yang terlihat, sehingga kamu tahu kebutuhan tercakup & pengeluaran terkendali.",hint:"Apa yang lebih menenangkan: menebak apakah uang cukup, atau melihat rencana yang menunjukkannya?"},
{n:54,type:"mcq",micro:"Anggaran & kebiasaan",q:"Setelah beberapa bulan menganggarkan, sebagian keputusan menjadi otomatis karena...",options:["Kamu berhenti memerlukan anggaran karena pengeluaran sudah sama tiap bulan tanpa dicatat lagi, jadi tinggal mengikuti arus","Kamu tahu polamu & batas tiap pos; anggaran berubah dari 'usaha sadar tiap kali' menjadi kebiasaan","Anggaran tak menjadi lebih mudah, sehingga terasa berat dan melelahkan walau dijalani lama sekali"],answer:1,explain:"Seperti keterampilan lain, menganggarkan jadi lebih mudah & cepat dengan latihan.",hint:"Apakah hal yang kamu lakukan berbulan-bulan tetap terasa sulit?"},
{n:55,type:"mcq",micro:"Anggaran & keputusan 'mampu atau tidak'",q:"Anggaran membantu menjawab 'apakah aku mampu membeli X' dengan lebih baik daripada 'apakah ada uang di dompet' karena...",options:["Tidak ada bedanya karena uang di dompet yang kelihatan banyak berarti bebas dipakai kapan saja untuk keperluan keluarga","Dompet lebih akurat daripada catatan anggaran karena uang di dompet bisa dilihat langsung setiap hari dan tak bisa salah hitung","Anggaran menunjukkan apakah uang di dompet sudah 'punya tugas lain' (kebutuhan, tabungan) — 'ada uang' tidak sama dengan 'bebas dipakai'"],answer:2,explain:"Uang yang ada belum tentu 'boleh dipakai' — sebagian sudah dialokasikan untuk kebutuhan/tabungan. Anggaran memperlihatkan uang yang benar-benar 'bebas'.",hint:"Apakah semua uang di dompetmu benar-benar bebas dibelanjakan?"},
{n:56,type:"mcq",micro:"Anggaran yang berkembang",q:"Seiring hidupmu berubah (kegiatan, tanggung jawab, pemasukan), anggaranmu sebaiknya...",options:["Ditinjau & disesuaikan; anggaran adalah dokumen hidup, bukan aturan beku","Tetap sama sejak pertama dibuat, tanpa perubahan walau kegiatan berbeda dan pemasukan naik","Dibuang dan jangan dibuat lagi, karena anggaran lama tak akan cocok"],answer:0,explain:"Anggaran yang tidak diperbarui saat keadaan berubah cepat menjadi tidak relevan.",hint:"Apakah anggaran tahun lalu masih cocok dengan hidupmu sekarang?"},
{n:57,type:"tf",micro:"Anggaran sederhana yang dijalankan mengalahkan yang rumit yang diabaikan",q:"Benar atau Salah: Anggaran 3–4 pos yang benar-benar kamu ikuti lebih berguna daripada anggaran 20 pos sangat rinci yang kamu tinggalkan setelah seminggu.",answer:true,explain:"Konsistensi lebih penting daripada kesempurnaan. Mulai sederhana; tambah rincian hanya bila membantu.",hint:"Mana yang membentuk kebiasaan: rencana yang dijalankan, atau rencana sempurna yang ditinggalkan?"},
{n:58,type:"mcq",micro:"Anggaran & melunasi utang",q:"Kalau kamu punya utang (mis. ke teman/keluarga), dalam anggaran sebaiknya...",options:["Abaikan utang karena utang kecil akan hilang sendiri bila dibiarkan beberapa bulan tanpa bunga dan denda","Ada pos khusus 'bayar utang' yang diprioritaskan sebelum keinginan — supaya utang berkurang teratur, bukan tertunda terus","Bayar utang hanya kalau ada sisa di akhir bulan, setelah keinginan dan jajan terpenuhi oleh anggota keluarga"],answer:1,explain:"Utang adalah kewajiban. Menempatkannya sebagai pos prioritas memastikan ia berkurang teratur & menjaga kepercayaan.",hint:"Kapan utang dibayar: sebelum atau sesudah keinginan?"},
{n:59,type:"mcq",micro:"Anggaran & pos yang terlalu kecil",q:"Kalau sebuah pos (mis. transport) terus kekurangan setiap minggu, itu tanda...",options:["Kamu harus berjalan kaki tiap hari bagaimanapun cuacanya supaya pos transport itu cukup sampai akhir minggu","Anggaran memang tak berguna, jadi lebih baik berhenti mencatat dan memakai uang sesuai kebutuhan hari itu","Perkiraanmu terlalu rendah; naikkan pos itu ke angka realistis & imbangi dengan memangkas pos lain"],answer:2,explain:"Pos yang selalu jebol biasanya berarti perkiraannya salah, bukan berarti kamu 'gagal'. Perbaiki angkanya.",hint:"Kalau angka rencana selalu kalah dari kenyataan, apa yang salah?"},
{n:60,type:"open",micro:"Menganalisis anggaran yang tidak seimbang",q:"Teman menunjukkan anggaran mingguannya: pemasukan Rp70.000; transport Rp15.000; makan Rp20.000; keinginan Rp40.000; tabungan Rp0. Ia sering pinjam untuk transport di akhir minggu. Analisis: (1) apa yang tidak seimbang, (2) risikonya, (3) susun ulang anggaran yang lebih sehat (angka konkret, total = Rp70.000), (4) satu aturan perilaku yang membantunya.",explain:"Jawaban baik mengenali defisit + keinginan yang mendominasi + tabungan nol + urutan salah (keinginan sebelum kebutuhan), menyebut risikonya, menyusun ulang dengan angka konkret yang total = pemasukan & memindahkan keinginan ke porsi wajar, & menambah aturan 'bayar diri sendiri & kebutuhan dulu'.",hint:"Masalahnya: keinginan terlalu besar, tabungan nol, & kebutuhan tidak diamankan lebih dulu.",sample:"(1) Tidak seimbang: total pos = Rp75.000 (defisit Rp5.000) & keinginan (Rp40.000) hampir 60% dari pemasukan — jauh lebih besar dari kebutuhan (Rp35.000) & tidak ada tabungan sama sekali. Ia membayar keinginan sebelum mengamankan kebutuhan → berutang untuk transport. (2) Risiko: utang menumpuk & merusak kepercayaan; tidak ada penyangga untuk kejutan; kebiasaan 'keinginan dulu' sulit diubah nanti; stres tiap akhir minggu. (3) Susun ulang (total Rp70.000): transport Rp16.000 (naik sedikit agar cukup); makan Rp20.000; tabungan Rp12.000 (disisihkan di awal minggu); keinginan Rp16.000; cadangan/lentur Rp6.000. Total = Rp70.000. (4) Aturan: 'Setiap Senin, langsung pisahkan transport untuk 5–6 hari & tabungan SEBELUM jajan apa pun.' Kalau pos keinginan habis di tengah minggu, tunggu minggu depan — jangan pinjam."},
{n:61,type:"mcq",micro:"Anggaran vs kebebasan",q:"Sebagian orang menghindari anggaran karena merasa 'mengekang'. Sudut pandang yang lebih tepat:",options:["Anggaran adalah keputusan yang kamu buat SEKALI di depan sehingga tidak perlu bergulat tiap kali — ini memberi kebebasan, bukan mengurangi","Anggaran memang mengekang kebebasan dan tak berguna, sehingga lebih baik tak dibuat sedikit pun, sebab kebebasan itu penting","Kebebasan berarti tak merencanakan apa-apa, karena merencanakan uang membuat hidup kaku dan kurang menyenangkan bagi pelajar di sekolah dan keluarganya"],answer:0,explain:"Anggaran mengalihkan keputusan dari 'momen godaan' ke 'saat tenang'. Kamu tetap yang memutuskan — hanya lebih awal & lebih jernih.",hint:"Apakah punya rencana perjalanan mengekang, atau membebaskanmu dari bingung di jalan?"},
{n:62,type:"tf",micro:"Anggaran mengungkap pilihan",q:"Benar atau Salah: Membuat anggaran menyembunyikan trade-off; dengan anggaran, kamu bisa menaikkan pos keinginan tanpa ada pos lain yang perlu turun.",answer:false,explain:"Justru anggaran memaksa kita menghadapi trade-off nyata: kalau pos keinginan naik, sesuatu yang lain harus turun. Anggaran membuat 'biaya peluang' terlihat — setiap rupiah untuk satu hal adalah rupiah yang tidak untuk hal lain.",hint:"Kalau kamu menambah satu pos, dari mana tambahan itu berasal?"},
{n:63,type:"mcq",micro:"Anggaran & rasa bersalah",q:"Kalau kamu melewati anggaran di satu pos suatu minggu, sikap yang produktif:",options:["Menghukum diri sendiri dengan keras dan memotong semua uang jajan minggu berikutnya sebagai balasan atas kesalahannya","Catat, cari sebab, & sesuaikan; sesekali menyimpang itu manusiawi — yang penting pola & kemampuan kembali ke jalur","Menyerah pada seluruh anggaran karena sudah gagal sekali, lalu berbelanja tanpa catatan seperti sebelum membuat rencana"],answer:1,explain:"Kesempurnaan bukan tujuan. Anggaran yang gagal di satu minggu tetap berguna kalau kamu kembali ke jalur minggu berikutnya.",hint:"Apakah satu penyimpangan berarti seluruh sistem gagal?"},
{n:64,type:"mcq",micro:"Anggaran & keadaan keluarga sulit",q:"Kalau pemasukan keluargamu tidak menentu & sering kurang, anggaran...",options:["Tidak berguna untuk keluarga yang kekurangan, karena uang yang sedikit tak mungkin diatur dengan rencana apa saja, sehingga cukup dipakai bila ada","Hanya berguna untuk keluarga yang punya uang lebih, sedangkan keluarga yang kekurangan cukup membelanjakan sesuai kebutuhan hari itu","Tetap berguna — bahkan lebih penting; ia membantu memastikan uang terbatas menutup kebutuhan pokok lebih dulu & mengenali di mana bisa dihemat"],answer:2,explain:"Justru saat uang paling terbatas, mengetahui prioritas & di mana bisa dipangkas paling menentukan.",hint:"Kapan lebih penting tahu 'apa yang harus dibayar dulu' — saat uang banyak atau sedikit?"},
{n:65,type:"tf",micro:"Anggaran bukan tentang jumlah, tapi tentang kendali",q:"Benar atau Salah: Manfaat utama anggaran bukan membuatmu punya lebih banyak uang, melainkan memberimu kendali & kejelasan tentang uang yang kamu punya.",answer:true,explain:"Anggaran mengubah hubunganmu dengan uang dari 'ke mana perginya ya?' menjadi 'aku yang memutuskan ke mana ia pergi'.",hint:"Apa yang anggaran ubah: jumlah uangmu, atau seberapa kamu mengendalikannya?"},
{n:66,type:"mcq",micro:"Menghindari 'anggaran dendam'",q:"Setelah beberapa minggu berhemat ketat, dorongan untuk 'balas dendam' dengan pengeluaran besar (splurge) sering muncul. Cara mencegahnya:",options:["Bangun ruang untuk kesenangan ke dalam anggaran sejak awal, sehingga tidak ada rasa 'terlalu lama menahan' yang memicu ledakan","Berhemat lebih ketat lagi dan menahan diri lebih lama, sehingga dorongan itu hilang dengan sendirinya setelah beberapa bulan berlalu","Tidak menikmati apa-apa dari uangmu sampai seluruh tujuan tabungan tercapai, bagaimanapun suasana hatimu, demi masa depan"],answer:0,explain:"Anggaran yang terlalu ketat memicu siklus 'menahan → meledak'. Ruang kesenangan yang terencana mencegahnya.",hint:"Apa yang terjadi setelah diet yang melarang semua makanan enak terlalu lama?"},
{n:67,type:"mcq",micro:"Anggaran & keputusan besar hidup",q:"Anggaran yang konsisten sejak muda membantu keputusan besar nanti (kuliah, kerja, tempat tinggal) karena...",options:["Keputusan besar seperti kuliah dan tempat tinggal tak membutuhkan perencanaan uang, jadi anggaran tidak diperlukan, karena orang tua yang menanggung semuanya","Kamu tahu berapa biaya hidupmu, punya kebiasaan mengelola, & mungkin sudah punya tabungan — sehingga pilihan lebih luas & lebih sedikit ketergantungan pada utang mahal","Tak berpengaruh pada keputusan besar apa saja, karena kebiasaan masa muda hilang sendiri saat dewasa nanti, dan penghasilan besar akan menyelesaikan semuanya"],answer:1,explain:"Orang yang terbiasa menganggarkan masuk ke keputusan besar dengan data & disiplin, bukan kebiasaan yang harus dibangun dari nol dalam tekanan.",hint:"Siapa yang lebih siap membuat keputusan keuangan besar: yang sudah terbiasa menganggarkan atau yang belum pernah?"},
{n:68,type:"tf",micro:"Anggaran tidak harus rumit untuk berguna",q:"Benar atau Salah: Anggaran hanya berguna kalau berbentuk spreadsheet rinci; rencana mental sederhana ('sisihkan tabungan & transport dulu, sisanya untuk seminggu') tidak lebih baik daripada tidak punya rencana.",answer:false,explain:"Bentuknya bisa sangat sederhana; yang penting ada rencana & batas. Bahkan anggaran mental sederhana sudah lebih baik daripada tidak ada rencana, & kerumitan bisa ditambah seiring kebutuhan.",hint:"Apakah anggaran harus berupa spreadsheet panjang untuk membantu?"},
{n:69,type:"mcq",micro:"Anggaran & inflasi",q:"Kalau harga-harga naik (inflasi), anggaranmu...",options:["Tidak terpengaruh karena harga transport naik tak mengubah pos lain di anggaran sehingga rencana lama tetap berlaku utuh untuk bulan depan","Harus tetap sama persis karena anggaran yang diubah-ubah menunjukkan perencanaan yang lemah dan membuat keluarga bingung","Perlu ditinjau: pos kebutuhan (makan, transport) mungkin harus naik, & tabungan/keinginan menyesuaikan atau pemasukan perlu ditambah"],answer:2,explain:"Anggaran mengikuti kenyataan biaya. Harga yang naik menuntut penyesuaian, bukan diabaikan.",hint:"Kalau angkot naik Rp1.000, apa yang terjadi pada pos transportmu?"},
{n:70,type:"order",micro:"Memutuskan pembelian besar dengan anggaran",q:"Kamu ingin membeli sesuatu yang besar (di luar pos rutin). Urutkan langkah memutuskannya dengan anggaran.",items:["Cek: apakah ada dana tujuan untuk ini, atau berapa lama menabung dengan menyisihkan X/bulan","Hitung biaya peluangnya (apa lagi yang bisa kamu lakukan dengan uang/waktu itu)","Bandingkan opsi: menabung untuk versi ini, versi lebih murah, atau tidak beli","Putuskan; kalau menabung, tambahkan sebagai pos anggaran & jalankan"],answer:[0,1,2,3],explain:"Cek keterjangkauan → biaya peluang → bandingkan opsi → putuskan & masukkan ke anggaran.",hint:"Anggaran mengubah 'aku mau' jadi 'ini butuh X bulan & mengorbankan Y'."},
{n:71,type:"mcq",micro:"Anggaran & pemasukan yang tidak kamu kendalikan",q:"Kamu bergantung pada uang saku yang jumlah & waktunya tidak selalu tetap dari orang tua. Sikap yang membantu:",options:["Buat anggaran dari jumlah minimum yang biasa kamu terima, komunikasikan dengan orang tua tentang kebutuhan tetap (transport), & sesuaikan saat pemasukan berubah","Anggap tidak bisa menganggarkan, sebab uang saku yang tak tetap tak mungkin direncanakan dengan baik bagi banyak orang, lalu catat nanti","Berutang kepada teman setiap kali uang saku terlambat datang, lalu dilunasi begitu uang saku berikutnya cair seluruhnya"],answer:0,explain:"Menganggarkan konservatif + komunikasi + fleksibilitas memungkinkan mengelola pemasukan yang tidak sepenuhnya kamu kontrol.",hint:"Bagaimana merencanakan dengan pemasukan yang naik-turun & kadang terlambat?"},
{n:72,type:"tf",micro:"Anggaran mencerminkan nilai",q:"Benar atau Salah: Cara seseorang mengalokasikan uang dalam anggaran (berapa untuk belajar, hobi, membantu keluarga, dll.) mencerminkan apa yang mereka anggap penting.",answer:true,explain:"Anggaran adalah 'pernyataan nilai dalam angka'. Ketidakcocokan antara nilai & alokasi adalah tanda untuk menyesuaikan.",hint:"Kalau kamu bilang belajar itu penting tapi tidak pernah menganggarkan untuk buku/kursus, apa yang ditunjukkan anggaranmu?"},
{n:73,type:"mcq",micro:"Anggaran & 'aku akan mulai nanti'",q:"Menunda membuat anggaran sampai 'penghasilanku lebih besar' berbahaya karena...",options:["Nanti lebih mudah membuat anggaran, karena pengeluaran seseorang tak ikut bertambah saat penghasilan bertambah, jadi tunggu sampai bekerja","Kebiasaan mengelola dibangun lewat latihan pada jumlah berapa pun; menunggu 'nanti' sering berarti tidak pernah, & pengeluaran ikut membesar seiring pemasukan","Anggaran memang hanya untuk orang berpenghasilan besar, jadi anak sekolah dengan uang saku kecil tidak perlu membuatnya"],answer:1,explain:"Menganggarkan uang saku Rp50.000 melatih keterampilan yang sama dengan menganggarkan gaji besar. Mulai sekarang.",hint:"Apakah orang yang tidak bisa mengatur sedikit tiba-tiba bisa mengatur banyak?"},
{n:74,type:"mcq",micro:"Anggaran & keputusan cepat",q:"Manfaat praktis anggaran dalam kehidupan sehari-hari:",options:["Membuat setiap keputusan menjadi lambat, rumit, dan melelahkan sehingga kamu lebih sering ragu daripada bertindak cepat","Melarang semua keputusan spontan sekecil apa saja, sehingga kamu tak boleh jajan atau membeli sesuatu mendadak lagi, demi disiplin","Banyak keputusan ('boleh jajan ini?', 'ikut kegiatan ini?') jadi cek cepat terhadap pos yang relevan, bukan pergulatan tiap kali"],answer:2,explain:"Anggaran yang sudah disusun mengubah pengambilan keputusan harian jadi cepat & tenang.",hint:"Apa yang anggaran bantu jawab dengan cepat di toko atau saat diajak teman?"},
{n:75,type:"mcq",micro:"Menyeimbangkan menabung & menikmati",q:"Anggaran yang sehat menyeimbangkan...",options:["Kebutuhan hari ini, kesenangan yang wajar sekarang, & tabungan untuk keamanan & tujuan masa depan — ketiganya, bukan mengorbankan satu sepenuhnya","Hanya tabungan semata, tanpa menikmati apa-apa dari uangmu sampai seluruh tujuan jangka panjang tercapai sepenuhnya, demi masa depan","Hanya kesenangan hari ini, sedangkan masa depan dan keamanan adalah urusan nanti yang tidak perlu dipikirkan sekarang"],answer:0,explain:"Ekstrem mana pun tidak berkelanjutan. Anggaran yang bertahan adalah yang seimbang & disengaja.",hint:"Apakah kamu harus memilih antara 'hidup sekarang' & 'aman nanti'?"},
{n:76,type:"tf",micro:"Anggaran adalah keterampilan yang dilatih",q:"Benar atau Salah: Kemampuan membuat & menjalankan anggaran berkembang dengan latihan, mencatat, & meninjau — bukan bakat yang dimiliki sebagian orang saja.",answer:true,explain:"Setiap periode anggaran yang kamu jalankan & tinjau menajamkan perkiraan & disiplinmu.",hint:"Apakah orang menjadi lebih baik menganggarkan setelah beberapa bulan berlatih?"},
{n:77,type:"mcq",micro:"Anggaran & keputusan kelompok",q:"Untuk kegiatan kelompok (acara kelas, klub), membuat anggaran bersama membantu karena...",options:["Anggaran hanya diperlukan untuk keuangan pribadi, sedangkan kegiatan kelompok cukup mengumpulkan uang lalu memakainya","Semua tahu berapa dana yang ada, ke mana perginya, & apakah cukup — mencegah kekacauan, defisit, & saling curiga","Membuat kegiatan lebih rumit dan lama tanpa manfaat bagi anggota kelompok yang ikut serta, terutama bagi bendahara"],answer:1,explain:"Anggaran kelompok yang transparan menjaga kepercayaan & memastikan dana terbatas menutup yang penting lebih dulu.",hint:"Apa yang terjadi pada dana kelompok tanpa rencana & pencatatan?"},
{n:78,type:"mcq",micro:"Anggaran yang tahan gagal",q:"Ciri anggaran yang lebih mungkin dijalankan berbulan-bulan:",options:["Sangat ketat dan rinci sampai ke recehan, tanpa ruang sedikit pun untuk hal spontan, kesenangan, maupun kejutan yang mungkin datang","Angka ideal yang dibuat sempurna di atas kertas, tetapi tak sesuai kenyataan sehingga tak diikuti dan dilacak oleh pembuatnya, walau terlihat indah","Realistis (dari pemasukan & pengeluaran nyata), sederhana (4–6 pos), menyisakan ruang untuk kesenangan & kejutan, mudah dilacak, & ditinjau berkala"],answer:2,explain:"Anggaran yang bertahan adalah yang manusiawi & bersistem, bukan yang paling keras.",hint:"Apa yang membuat sebuah rencana benar-benar dijalankan, bukan ditinggalkan?"},
{n:79,type:"mcq",micro:"Anggaran & masa depan yang tidak pasti",q:"Anggaran membantu menghadapi masa depan yang tidak pasti dengan...",options:["Membangun dana darurat & kebiasaan yang membuatmu lebih tahan menghadapi kejutan (biaya mendadak, pemasukan turun)","Menjamin tak ada kejutan lagi dalam hidupmu, karena semua pengeluaran sudah direncanakan dengan sempurna lebih dulu","Tidak membantu menghadapi masa depan, sebab masa depan tak terduga sehingga tak ada gunanya merencanakan sesuatu"],answer:0,explain:"Anggaran tidak menghapus ketidakpastian, tapi menyiapkanmu: penyangga darurat + kebiasaan mengelola = lebih siap.",hint:"Apa yang anggaran berikan saat kejutan biaya datang?"},
{n:80,type:"open",micro:"Merancang anggaran yang bisa bertahan",q:"Seorang teman berkata: 'Aku sudah 3 kali membuat anggaran rinci, tapi selalu berhenti dalam seminggu karena terlalu ribet & terasa mengekang.' Bantu ia: (1) apa yang mungkin salah dengan pendekatannya, (2) rancang anggaran 'versi minimal' yang lebih mungkin ia jalankan, (3) cara melacak yang tidak ribet, (4) bagaimana menambah rincian nanti secara bertahap.",explain:"Jawaban baik mengenali 'terlalu rinci + terlalu ketat sejak awal' sebagai penyebab menyerah, merancang anggaran 3-pos minimal dengan 'kantong bebas' yang menghilangkan rasa mengekang & pelacakan berat, cara melacak ringan (lihat kantong, bukan catat semua), & jalur menambah rincian bertahap setelah kebiasaan terbentuk.",hint:"Untuk pemula yang sering menyerah: mulai dari 3 pos & 'kantong bebas', bukan spreadsheet rinci.",sample:"(1) Salah: terlalu rinci sejak awal (banyak kategori) sehingga melacaknya melelahkan; kemungkinan juga terlalu ketat (tidak ada ruang untuk kesenangan/spontan) sehingga terasa mengekang & memicu 'menyerah'. (2) Versi minimal — 3 pos saja: (a) Kebutuhan & wajib (transport + makan) — perkirakan totalnya, sisihkan di awal minggu; (b) Tabungan — satu angka tetap, disisihkan bersamaan; (c) 'Sisanya bebas untuk seminggu' — satu kantong yang boleh dipakai untuk apa saja (jajan, hiburan, spontan) sampai habis. Contoh dari Rp70.000: kebutuhan Rp32.000, tabungan Rp12.000, bebas Rp26.000. (3) Pelacakan tidak ribet: tidak perlu mencatat tiap pengeluaran — cukup lihat 'kantong bebas' setiap hari; kalau tinggal sedikit di hari Kamis, tahan sampai minggu depan. Atau catat hanya total harian sekali. (4) Menambah rincian bertahap: setelah 1 bulan lancar dengan 3 pos, kalau ingin tahu lebih detail, pecah 'kantong bebas' jadi 'jajan' & 'hiburan'; setelah itu tambahkan 'dana tujuan' terpisah. Tambah satu lapisan tiap kali yang lama sudah jadi kebiasaan."},
{n:81,type:"mcq",micro:"Kerangka anggaran",q:"Kerangka singkat membuat anggaran yang berhasil:",options:["Menabung dari sisa saja; tidak perlu membuat pos; abaikan pengeluaran nyata dan pakai angka perkiraan yang kamu sukai saja tanpa pernah mengecek hasilnya","Hitung pemasukan (konservatif bila tidak tetap); alokasikan ke pos sampai sisa nol dengan kebutuhan & tabungan lebih dulu; sisakan ruang untuk kesenangan & kejutan; buat sederhana & mudah dilacak; tinjau & sesuaikan tiap periode","Buat serinci mungkin tanpa ruang untuk kesenangan dan kejutan; jangan ditinjau ulang; dan pertahankan angka yang sama dalam jangka panjang bagaimanapun yang terjadi pada keluarga mana pun, sebagaimana biasanya"],answer:1,explain:"Pemasukan → alokasi (kebutuhan & tabungan dulu, total = pemasukan) → ruang untuk kesenangan & kejutan → sederhana & terlacak → tinjau.",hint:"Gabungkan: pemasukan + alokasi (kebutuhan & tabungan dulu) + ruang kesenangan + sederhana + tinjau."},
{n:82,type:"mcq",micro:"Anggaran pada tingkat pemasukan berapa pun",q:"'Membuat anggaran' relevan bagi...",options:["Hanya untuk orang yang berpenghasilan besar, sedangkan orang dengan uang sedikit tak memerlukan rencana untuk uangnya","Hanya untuk orang dewasa yang sudah bekerja, sehingga pelajar dan anak-anak tidak perlu belajar merencanakan uang saku mereka","Semua orang, pada tingkat pemasukan berapa pun — yang berubah hanya besaran & jenis pos, bukan pentingnya merencanakan"],answer:2,explain:"Prinsip 'beri tiap rupiah tujuan, kebutuhan & tabungan dulu' berlaku universal.",hint:"Apakah membagi uang ke pos hanya untuk yang punya banyak?"},
{n:83,type:"tf",micro:"Anggaran melengkapi keterampilan keuangan lain",q:"Benar atau Salah: Anggaran menjadi kerangka yang menghubungkan keterampilan keuangan lain — membedakan kebutuhan/keinginan, menabung untuk tujuan, menghindari utang buruk, & menjadi konsumen cerdas.",answer:true,explain:"Anggaran adalah tempat semua keputusan keuangan bertemu: ia memberi konteks & batas untuk semuanya.",hint:"Di mana keputusan 'kebutuhan atau keinginan', 'menabung berapa', & 'utang atau tidak' bertemu?"},
{n:84,type:"mcq",micro:"Anggaran & tujuan hidup",q:"Anggaran yang baik pada akhirnya adalah tentang...",options:["Mengarahkan uang yang terbatas ke hal-hal yang paling penting bagimu — keamanan, tujuan, & hidup yang kamu inginkan","Mengeluarkan uang sesedikit mungkin dalam setiap kesempatan, karena makin kecil pengeluaran makin baik anggaran itu","Membuat hidup terasa serba dibatasi dan penuh larangan, karena itulah tujuan utama dari setiap orang yang membuat anggaran"],answer:0,explain:"Tujuan anggaran bukan pelit, melainkan memastikan uangmu melayani prioritas & nilaimu.",hint:"Untuk apa sebenarnya kamu membuat anggaran?"},
{n:85,type:"order",micro:"Siklus anggaran lengkap",q:"Urutkan siklus anggaran satu periode penuh.",items:["Susun: alokasikan pemasukan ke pos (kebutuhan & tabungan dulu, total = pemasukan)","Jalankan: belanjakan sesuai pos; catat pengeluaran","Tinjau: bandingkan nyata vs rencana; cari sebab selisih","Sesuaikan: perbaiki angka pos & aturan untuk periode berikutnya, lalu ulangi"],answer:[0,1,2,3],explain:"Susun → jalankan & catat → tinjau → sesuaikan & ulangi. Anggaran adalah siklus, bukan tugas sekali.",hint:"Setelah menjalankan & mencatat, apa yang kamu lakukan sebelum menyusun periode berikutnya?"},
{n:86,type:"mcq",micro:"Mengajari anggaran",q:"Cara terbaik membantu adik/teman mulai menganggarkan:",options:["Buatkan saja anggaran yang sangat rinci untuknya sampai ke recehan, walaupun ia tidak memahami cara membaca dan memakainya sendiri, sebagaimana biasanya","Bantu ia membuat versi paling sederhana (kebutuhan / tabungan / sisa-bebas) untuk uang sakunya, jalankan seminggu, lalu tinjau bersama — sukses awal yang kecil membangun kebiasaan","Beri ia ceramah panjang tentang pentingnya anggaran sampai ia mengerti, tanpa membantunya mencoba langsung dengan uang sakunya"],answer:1,explain:"Pengalaman berhasil menjalankan anggaran sederhana selama satu periode adalah guru terbaik.",hint:"Apa yang membuat seseorang percaya 'aku bisa menganggarkan'?"},
{n:87,type:"tf",micro:"Anggaran mengubah hubungan dengan uang",q:"Benar atau Salah: Menjalankan anggaran secara konsisten tidak mengubah hubunganmu dengan uang — kamu tetap sama cemasnya & reaktif seperti sebelum punya anggaran.",answer:false,explain:"Anggaran yang dijalankan konsisten mengubah hubungan itu dari cemas & reaktif menjadi tenang & terarah — mengganti 'cukup nggak ya?' dengan 'aku tahu ke mana uangku pergi & kebutuhanku tercakup'.",hint:"Apa yang anggaran ganti: ketidakpastian, atau jumlah uangmu?"},
{n:88,type:"mcq",micro:"Menutup: membuat anggaran",q:"Sikap paling berguna:",options:["Buat anggaran serinci mungkin dengan angka ideal, lalu abaikan ketika pengeluaran nyata tak sesuai; tinjau hanya bila uang sudah habis, dan catat semua pengeluaran sampai ke receh agar terlihat rapi di buku khusus yang dibeli baru","Jangan membuat anggaran; belanjakan uang mengikuti keadaan dan suasana hati, dan cari pinjaman bila uangnya tidak cukup, karena anggaran hanya membatasi kebahagiaan dan membuat hidup terasa kaku serta membosankan","Buat anggaran sederhana dan jujur sesuai pemasukan & pengeluaran nyata; beri tiap rupiah tujuan (kebutuhan & tabungan dulu); sisakan ruang untuk kesenangan; tinjau berkala; anggaran adalah alat, bukan hukuman"],answer:2,explain:"Inti: sederhana & jujur + tiap rupiah punya tujuan (kebutuhan & tabungan dulu) + ruang untuk hidup + lacak & tinjau + sesuaikan.",hint:"Gabungkan: sederhana & jujur + tiap rupiah punya tujuan + ruang untuk hidup + lacak & tinjau."},
{n:89,type:"mcq",micro:"Ringkasan: membuat anggaran",q:"Rangkuman paling tepat:",options:["Anggaran adalah rencana membagi pemasukan ke pos (kebutuhan, tabungan/darurat, tujuan, keinginan, cadangan) sampai sisa nol; sederhana, jujur pada angka nyata, dilacak & ditinjau tiap periode, dan disesuaikan saat keadaan berubah","Anggaran berarti tak boleh membelanjakan uang untuk hal menyenangkan sedikit pun; semua pemasukan disimpan, tak perlu dilacak atau ditinjau, tak boleh diubah walau hidup berubah, dan pos darurat tak diperlukan karena cukup di dompet","Anggaran hanya untuk orang dewasa berpenghasilan besar; pelajar tak perlu menyusunnya karena uang sakunya kecil, tak perlu pos tabungan atau dana darurat; cukup mencatat pengeluaran di akhir bulan tanpa tinjauan atau penyesuaian"],answer:0,explain:"Anggaran = alokasi pemasukan ke pos (kebutuhan & tabungan dulu, total = pemasukan), sederhana & jujur, ada ruang untuk hidup, dilacak & ditinjau, disesuaikan — keterampilan yang dilatih.",hint:"Gabungkan: alokasi ke pos + prioritas + sederhana & jujur + ruang untuk hidup + lacak & tinjau + sesuaikan."},
{n:90,type:"tf",micro:"Anggaran fleksibel lebih kuat dari anggaran kaku",q:"Benar atau Salah: Anggaran yang menyisakan ruang untuk penyesuaian & kesenangan cenderung bertahan lebih lama daripada anggaran yang sangat kaku tanpa toleransi apa pun.",answer:true,explain:"Kelenturan membuat anggaran menahan kejutan hidup tanpa 'patah'. Kekakuan sering berujung ditinggalkan.",hint:"Apa yang terjadi pada rencana yang tidak punya toleransi terhadap satu pun penyimpangan?"},
{n:91,type:"mcq",micro:"Tiga prinsip praktis",q:"Tiga prinsip praktis membuat anggaran:",options:["Menabung dari sisa saja; jangan buat pos; abaikan pengeluaran nyata dan pakai perkiraan yang kamu sukai, tanpa meninjau hasilnya setiap bulan setiap saat","Beri tiap rupiah tujuan (kebutuhan & tabungan lebih dulu, total = pemasukan); buat sederhana & jujur pada angka nyata; & lacak lalu tinjau tiap periode untuk menyesuaikan","Buat serinci mungkin; pakai angka ideal yang indah di atas kertas; dan jangan pernah ditinjau ulang walau pengeluaran nyatamu sangat berbeda"],answer:1,explain:"Tiap rupiah punya tujuan + sederhana & jujur + lacak & tinjau = inti anggaran yang berhasil.",hint:"Gabungkan: tiap rupiah punya tujuan + sederhana & jujur + lacak & tinjau."},
{n:92,type:"open",micro:"Kapstone: anggaran pribadi 3 bulan + rencana peninjauan",q:"Buat anggaran pribadi 3 bulan. Sertakan: (1) perkiraan pemasukan bulanan (konservatif bila tidak tetap), (2) pos kebutuhan tetap + biaya, (3) pos tabungan darurat + target, (4) 1–2 dana tujuan + jumlah bulanan, (5) pos keinginan & cadangan/lentur, (6) total (harus = pemasukan; tunjukkan berbasis nol), (7) alat & cara melacak, (8) jadwal & pertanyaan peninjauan bulanan, (9) rencana bila pemasukan turun di salah satu bulan.",explain:"Kapstone menggabungkan semuanya: pemasukan konservatif, alokasi berbasis nol dengan kebutuhan & tabungan diprioritaskan, dana darurat & tujuan sebagai pos, ruang untuk keinginan & lentur, alat & rutinitas pelacakan ringan, jadwal & pertanyaan tinjauan, & rencana kontinjensi untuk bulan pemasukan rendah (urutan pemangkasan yang jelas).",hint:"Total harus = pemasukan; tunjukkan urutan pemangkasan yang jelas untuk bulan yang kurang (keinginan & lentur dulu, lindungi kebutuhan & darurat).",sample:"Contoh: (1) Pemasukan konservatif: Rp300.000/bulan (uang saku Rp240.000 + bantu paman Rp60.000, memakai angka terendah yang biasa). (2) Kebutuhan: transport Rp85.000, makan Rp90.000, keperluan sekolah Rp25.000 = Rp200.000. (3) Dana darurat: Rp25.000/bulan, target Rp150.000 (tercapai bulan ke-6, jadi lanjut setelah 3 bulan ini). (4) Dana tujuan: sepatu lari Rp30.000/bulan; kado ibu Rp15.000/bulan. (5) Keinginan Rp15.000/bulan; cadangan/lentur Rp15.000. (6) Total: 200 + 25 + 30 + 15 + 15 + 15 = Rp300.000 = pemasukan ✓ (berbasis nol). (7) Alat: aplikasi catatan ponsel, satu halaman per bulan; catat tiap pengeluaran per pos setiap hari (30 detik). (8) Tinjauan: setiap tanggal 1, tanyakan — pos mana yang meleset & seberapa? apa sebabnya (perkiraan salah / kejutan / kebiasaan)? apakah dana darurat & tujuan bertambah sesuai rencana? apa satu perubahan untuk bulan depan? (9) Bila pemasukan turun (mis. paman tidak butuh bantuan sebulan): potong dulu keinginan (Rp15.000→Rp5.000) & cadangan (Rp15.000→Rp5.000) & tunda kado ibu bulan itu (Rp15.000); lindungi kebutuhan, darurat, & sepatu; kembalikan ke normal bulan berikutnya."},
{n:93,type:"mcq",micro:"Menilai sebuah anggaran",q:"Anggaran yang layak dipuji...",options:["Menyisihkan 95% dari semua pemasukan dan melarang diri menikmati kesenangan, supaya tabungan cepat bertambah dan tak ada godaan, walau kebutuhan pokok terganggu di rumah","Defisit yang ditutup dengan pinjaman baru setiap bulan, tanpa dana darurat, tanpa tujuan, dan tanpa jadwal tinjauan yang teratur, sebagaimana biasanya dilakukan oleh keluarga","Total = pemasukan (tidak defisit), kebutuhan & tabungan/darurat sebagai prioritas, punya dana tujuan, menyisakan ruang untuk kesenangan & kejutan, sederhana & dilacak, & ada jadwal tinjauan"],answer:2,explain:"Anggaran baik seimbang, berprioritas, berkelanjutan, & hidup (dilacak & ditinjau) — bukan ekstrem atau defisit kronis.",hint:"Apa ciri anggaran yang benar-benar dijalankan & mencapai tujuan?"},
{n:94,type:"mcq",micro:"Anggaran & identitas",q:"Orang yang berpikir 'aku adalah orang yang mengelola uangnya dengan sadar' (bukan 'aku sedang mencoba berhemat')...",options:["Cenderung lebih konsisten, karena menganggarkan menjadi bagian dari siapa mereka, bukan tugas berat sementara","Tidak ada bedanya karena anggaran hanya soal jumlah uang yang dimiliki seseorang saat ini sendiri","Lebih mungkin menyerah karena menganggarkan terasa seperti hukuman bagi mereka yang berpenghasilan kecil dan jarang punya sisa uang"],answer:0,explain:"Kebiasaan yang menjadi identitas lebih tahan lama daripada yang dirasa sebagai perjuangan.",hint:"Apa bedanya 'aku mencoba berhemat' & 'aku orang yang mengelola uang dengan sadar'?"},
{n:95,type:"tf",micro:"Anggaran memberi kebebasan, bukan mengekang",q:"Benar atau Salah: Anggaran selalu membuat setiap pengeluaran keinginan terasa bersalah, karena ia sepenuhnya melarang uang dipakai untuk kesenangan.",answer:false,explain:"Anggaran yang dijalankan dengan baik justru memberi kebebasan: kamu bisa membelanjakan pos 'keinginan' tanpa rasa bersalah, karena kamu tahu kebutuhan & tabungan sudah aman & uang itu memang boleh dipakai.",hint:"Bagaimana perasaanmu membelanjakan uang yang kamu TAHU boleh dibelanjakan?"},
{n:96,type:"mcq",micro:"Anggaran untuk peluang, bukan hanya pertahanan",q:"Selain melindungi dari masalah, anggaran juga membantu...",options:["Tidak berhubungan dengan peluang, karena anggaran hanya dipakai mengatur pengeluaran sehari-hari yang sudah terjadi","Mengumpulkan dana untuk peluang (kursus, alat hobi/usaha, biaya lomba) — sehingga saat kesempatan datang, kamu siap","Hanya berguna menghindari kekurangan uang di akhir bulan, sehingga tak ada kaitannya dengan kursus, hobi, atau usaha"],answer:1,explain:"Anggaran dengan dana tujuan membuatmu proaktif: kamu menyiapkan uang untuk hal-hal yang membuka pintu, bukan hanya bertahan.",hint:"Apa yang kamu punya saat peluang datang & kamu sudah menganggarkan untuknya?"},
{n:97,type:"mcq",micro:"Inti yang dibawa pulang",q:"Satu gagasan inti tentang membuat anggaran:",options:["Anggaran berarti hidup serba hemat dan tanpa kesenangan, karena tujuan utamanya membatasi diri sekeras mungkin tiap bulan, sebagaimana biasanya, dan itu dianggap baik oleh guru","Anggaran hanya berguna bagi orang yang punya banyak uang, sedangkan uang sedikit tak mungkin diatur dan diarahkan ke tujuan yang jelas, apalagi bagi pelajar yang masih bergantung pada orang tua","Anggaran bukan tentang membatasi diri, melainkan tentang secara sadar mengarahkan uangmu yang terbatas ke hal-hal yang paling penting bagimu — memberimu kendali, kejelasan, & kemampuan mencapai tujuan"],answer:2,explain:"Anggaran adalah alat untuk mengambil kemudi atas uangmu & mengarahkannya ke prioritas & tujuanmu.",hint:"Apakah anggaran tentang membatasi, atau tentang mengarahkan?"},
{n:98,type:"mcq",micro:"Menghubungkan ke keterampilan lain",q:"Membuat anggaran adalah kerangka yang menopang...",options:["Menabung untuk tujuan, menghindari & melunasi utang, menjadi konsumen cerdas, mengejar peluang, & pada akhirnya berinvestasi — semua berjalan di dalam anggaran","Tidak berhubungan dengan keterampilan keuangan lain, karena anggaran kegiatan mencatat yang berdiri sendiri tanpa kaitan dengan tabungan, utang, atau investasi","Hanya berguna mencatat pengeluaran yang sudah terjadi di masa lalu, sehingga tak membantu menabung, melunasi utang, ataupun mengejar peluang masa depan"],answer:0,explain:"Hampir setiap keputusan & keterampilan keuangan lain terjadi di dalam kerangka anggaran.",hint:"Di mana keputusan menabung, berutang, & berbelanja semuanya dijalankan?"},
{n:99,type:"tf",micro:"Anggaran adalah dokumen hidup",q:"Benar atau Salah: Anggaran sebaiknya diperbarui saat pemasukan, biaya, tujuan, & keadaan hidupmu berubah — bukan dibuat sekali lalu dianggap final.",answer:true,explain:"Anggaran yang tidak mengikuti kenyataan cepat menjadi tidak berguna. Meninjaunya berkala menjaganya tetap relevan.",hint:"Apakah anggaran yang dibuat setahun lalu masih cocok dengan hidupmu sekarang?"},
{n:100,type:"open",micro:"Kapstone: panduan 'Membuat Anggaran Pertamamu' untuk teman sebaya",q:"Tulis panduan singkat (8–10 poin) berjudul 'Membuat Anggaran Pertamamu' untuk teman sebayamu. Cakup: apa itu anggaran & gunanya, hitung pemasukan, beri tiap rupiah tujuan (kebutuhan & tabungan dulu), mulai sederhana (3–5 pos), sisakan ruang untuk kesenangan & kejutan, cara melacak yang tidak ribet, meninjau rencana vs kenyataan, menyesuaikan saat meleset atau keadaan berubah, & bahwa anggaran memberi kebebasan bukan mengekang. Gunakan bahasa jelas & contoh angka.",explain:"Panduan baik menyederhanakan semua prinsip: definisi & guna, hitung pemasukan (konservatif), tiap rupiah punya tujuan (kebutuhan & tabungan dulu), mulai sederhana dengan contoh angka, ruang untuk kesenangan & kejutan, pelacakan ringan, tinjau rencana vs kenyataan, sesuaikan, perbarui, & bingkai anggaran sebagai kebebasan — dengan bahasa ramah sebaya.",hint:"Tiap poin harus bisa langsung dipakai teman sebayamu untuk membuat anggaran pertamanya minggu ini.",sample:"Contoh panduan: 1) Anggaran = rencana membagi uangmu SEBELUM dibelanjakan, supaya tidak ada yang 'hilang tanpa jejak'. Gunanya: kebutuhan tercakup, tujuan tercapai, & tenang. 2) Hitung pemasukanmu seminggu/sebulan (uang saku + hadiah + hasil kerja). Kalau tidak tetap, pakai angka terendah yang biasa. 3) Beri tiap rupiah tujuan. Sisihkan KEBUTUHAN (transport, makan) & TABUNGAN lebih dulu — sebelum jajan apa pun. 4) Mulai sederhana: 3–5 pos saja. Contoh dari Rp60.000/minggu: kebutuhan Rp30.000, tabungan Rp12.000, keinginan Rp12.000, cadangan Rp6.000. 5) Sisakan ruang untuk kesenangan & kejutan (pos keinginan + cadangan) — anggaran tanpa hiburan tidak akan bertahan. 6) Lacak dengan mudah: catat pengeluaran singkat di aplikasi catatan ponsel, ATAU pakai amplop terpisah & cukup lihat isinya. 7) Di akhir minggu/bulan, bandingkan: apa yang kamu rencanakan vs apa yang benar-benar terjadi? Pos mana yang meleset? 8) Sesuaikan: kalau pos transport selalu kurang, naikkan angkanya & kurangi pos lain. Kalau keinginan selalu jebol, buat aturan (mis. 'jajan minuman maksimal 2x'). 9) Perbarui anggaran saat keadaan berubah (transport lebih jauh, uang saku naik). Anggaran itu hidup, bukan aturan beku. 10) Ingat: anggaran BUKAN 'kamu tidak boleh'. Ia 'inilah rencanamu' — & setelah kebutuhan & tabungan aman, kamu bisa memakai pos keinginan tanpa rasa bersalah."},
];
